import { workflow, node, trigger, sticky, expr, ifElse } from '@n8n/workflow-sdk';
const aboutNote = sticky("SF8c v-next - People Review Write-Back (C10). Mirrors SF8b's pattern for the People tab: reads the v-next Sheet COPY People tab, validates the company_id/Person/person_key/Decision/Note headers (missing header = zero writes + Gmail draft naming it), records each decision in people_reviews (idempotent on person_key+decision), and applies REJECTED decisions to tavily_xray people only: the people row is DELETE-d (freeing its LinkedIn URL from the unique index) and an audit event is written to people_search_events. Approved/hold decisions are recorded only. Until this runs, 100% per-save audit of SF6d people remains mandatory (Wonder C10).", [], { color: 5 });

const subTrigger = trigger({
  type: 'n8n-nodes-base.executeWorkflowTrigger',
  version: 1.1,
  config: {
    name: 'When Executed by Another Workflow',
    parameters: {
      workflowInputs: { values: [
        { name: 'decided_by', type: 'string' }
      ] }
    },
    position: [40, 400]
  },
  output: [{ decided_by: 'sheet:People (v-next)' }]
});

const readNode = node({
  type: 'n8n-nodes-base.googleSheets',
  version: 4.2,
  config: {
    name: 'Sheet - Read People Decisions',
    alwaysOutputData: true,
    position: [320, 400],
    parameters: {
      resource: 'sheet',
      operation: 'read',
      documentId: { __rl: true, mode: 'id', value: "1dF2mdjUFc6D0jFTvhxbby6DJxWo4T6Fw0UrWEHI20JM", cachedResultName: 'Lead Finder - Approval View (v-next F32)' },
      sheetName: { __rl: true, mode: 'name', value: 'People', cachedResultName: 'People' },
      options: {}
    }
  },
  output: [{ company_id: 'uuid', Person: 'Name', person_key: 'uuid|Name', Decision: '' }]
});

const existNode = node({
  type: 'n8n-nodes-base.postgres',
  version: 2.6,
  config: {
    name: 'DB - Existing People Reviews',
    alwaysOutputData: true,
    position: [600, 400],
    parameters: {
      operation: 'executeQuery',
      query: "SELECT person_key, decision, COALESCE(note, '') AS note FROM people_reviews",
      options: {}
    }
  },
  output: [{ person_key: 'uuid|Name', decision: 'approved', note: '' }]
});

const collectNode = node({
  type: 'n8n-nodes-base.code',
  version: 2,
  config: {
    name: 'Collect People Decisions',
    parameters: { mode: 'runOnceForAllItems', jsCode: "const REQUIRED = ['company_id', 'Person', 'person_key', 'Decision', 'Note'];\nconst rows = $('Sheet - Read People Decisions').all().map(i => i.json);\nconst headerSet = new Set();\nfor (const r of rows) for (const k of Object.keys(r)) headerSet.add(k);\nconst missing = headerSet.size ? REQUIRED.filter(h => !headerSet.has(h)) : [];\nconst trig = $('When Executed by Another Workflow').item.json;\nif (missing.length) {\n  return [{ json: { header_error: missing[0], missing_headers: missing, payload: '[]', count: 0, skipped_duplicate: 0, decided_by: trig.decided_by || 'sheet:People (v-next)' } }];\n}\nconst ok = { approved: 1, rejected: 1, hold: 1 };\nconst existing = new Set($('DB - Existing People Reviews').all().map(i => {\n  const j = i.json; return String(j.person_key) + '|' + String(j.decision) + '|' + String(j.note || '');\n}));\nconst byKey = new Map();\nfor (const r of rows) {\n  const d = String(r.Decision || '').trim().toLowerCase();\n  if (!r.company_id || !r.Person || !r.person_key || !ok[d]) continue;\n  byKey.set(String(r.person_key), { person_key: String(r.person_key), company_id: String(r.company_id), full_name: String(r.Person), decision: d, note: String(r.Note || '') });\n}\nconst fresh = [];\nlet skippedDup = 0;\nfor (const dec of byKey.values()) {\n  if (existing.has(dec.person_key + '|' + dec.decision + '|' + dec.note)) skippedDup++;\n  else fresh.push(dec);\n}\nreturn [{ json: { header_error: '', payload: JSON.stringify(fresh), count: fresh.length, skipped_duplicate: skippedDup, decided_by: trig.decided_by || 'sheet:People (v-next)' } }];" },
    position: [880, 400]
  },
  output: [{ payload: '[]', count: 0, skipped_duplicate: 0, decided_by: 'sheet', header_error: '' }]
});

const headerGate = ifElse({
  type: 'n8n-nodes-base.if',
  version: 2.2,
  config: {
    name: 'Header OK?',
    position: [1160, 400],
    parameters: {
      conditions: {
        options: { caseSensitive: true, leftValue: '', typeValidation: 'loose' },
        conditions: [{ id: 'herr', leftValue: expr("{{ $json.header_error }}"), rightValue: '', operator: { type: 'string', operation: 'empty', singleValue: true } }],
        combinator: 'and'
      },
      options: {}
    }
  }
});

const recNode = node({
  type: 'n8n-nodes-base.postgres',
  version: 2.6,
  config: {
    name: "DB - Record People Reviews",
    alwaysOutputData: true,
    position: [1440, 320],
    parameters: {
      operation: 'executeQuery',
      query: "WITH items AS (SELECT x FROM jsonb_array_elements($1::jsonb) AS x)\nINSERT INTO people_reviews (person_key, company_id, full_name, decision, decided_by, note)\nSELECT x->>'person_key', (x->>'company_id')::uuid, x->>'full_name', x->>'decision', $2, NULLIF(x->>'note','')\nFROM items x\nWHERE NOT EXISTS (SELECT 1 FROM people_reviews r WHERE r.person_key = x->>'person_key' AND r.decision = x->>'decision')\nRETURNING person_key",
      options: { queryReplacement: expr('{{ [ $(\'Collect People Decisions\').item.json.payload, $(\'Collect People Decisions\').item.json.decided_by ] }}') }
    }
  },
  output: [{}]
});

const applyNode = node({
  type: 'n8n-nodes-base.postgres',
  version: 2.6,
  config: {
    name: "DB - Apply People Rejections",
    alwaysOutputData: true,
    position: [1720, 320],
    parameters: {
      operation: 'executeQuery',
      query: "WITH items AS (SELECT x FROM jsonb_array_elements($1::jsonb) AS x),\ndel AS (\n  DELETE FROM people p\n  USING items x\n  WHERE x->>'decision' = 'rejected'\n    AND p.company_id = (x->>'company_id')::uuid\n    AND p.full_name = x->>'full_name'\n    AND p.source = 'tavily_xray'\n  RETURNING p.company_id, p.full_name, p.linkedin_url\n),\nev AS (\n  INSERT INTO people_search_events (run_id, company_id, workflow, stage, detail)\n  SELECT 'sheet-review', d.company_id, 'SF8c', 'people_review',\n         jsonb_build_object('outcome', 'rejected_deleted', 'full_name', d.full_name, 'linkedin_url', d.linkedin_url)\n  FROM del d\n  RETURNING id\n)\nSELECT (SELECT count(*) FROM del)::int AS deleted, (SELECT count(*) FROM ev)::int AS events",
      options: { queryReplacement: expr('{{ [ $(\'Collect People Decisions\').item.json.payload, $(\'Collect People Decisions\').item.json.decided_by ] }}') }
    }
  },
  output: [{ deleted: 0, events: 0 }]
});

const errPrepNode = node({
  type: 'n8n-nodes-base.code',
  version: 2,
  config: {
    name: 'Prep Header Error',
    parameters: { mode: 'runOnceForAllItems', jsCode: "const c = $('Collect People Decisions').first().json;\nreturn [{ json: { subject: 'SF8c v-next header error - missing header: ' + (c.header_error || ''), text: 'SF8c v-next (C10) refused to write back any people decisions.\\nMissing/renamed header: ' + (c.header_error || '') + '\\nAll missing: ' + JSON.stringify(c.missing_headers || []) + '\\nZero people reviews were recorded. Rename the header back to continue.' } }];" },
    position: [1300, 560]
  },
  output: [{ subject: 'x', text: 'y' }]
});

const errDraftNode = node({
  type: 'n8n-nodes-base.gmail',
  version: 2.1,
  config: {
    name: 'Gmail - Header Error Draft (C10)',
    position: [1580, 560],
    parameters: {
      resource: 'draft',
      operation: 'create',
      subject: expr('{{ $json.subject }}'),
      emailType: 'text',
      message: expr('{{ $json.text }}'),
      options: {}
    }
  },
  output: [{ id: 'draft' }]
});

const retNode = node({
  type: 'n8n-nodes-base.code',
  version: 2,
  config: {
    name: 'Return',
    parameters: { mode: 'runOnceForAllItems', jsCode: "const c = $('Collect People Decisions').item.json;\nconst recorded = $('DB - Record People Reviews').all().length;\nconst applied = $('DB - Apply People Rejections').all();\nconst deleted = applied.length ? (applied[0].json.deleted || 0) : 0;\nreturn [{ json: { success: true, recorded, deleted, skipped_duplicate: c.skipped_duplicate || 0, decisions_seen: (c.count || 0) + (c.skipped_duplicate || 0) } }];" },
    position: [2000, 320]
  },
  output: [{ success: true, recorded: 0, deleted: 0, skipped_duplicate: 0, decisions_seen: 0 }]
});

const retErrNode = node({
  type: 'n8n-nodes-base.code',
  version: 2,
  config: {
    name: 'Return - Header Error',
    parameters: { mode: 'runOnceForAllItems', jsCode: "const c = $('Collect People Decisions').first().json; return [{ json: { success: false, header_error: c.header_error || '', recorded: 0, deleted: 0 } }];" },
    position: [1860, 560]
  },
  output: [{ success: false, header_error: '' }]
});

export default workflow('leadfinder-sf8c-vnext', 'SF8c v-next - People Review Write-Back (C10)')
  .add(aboutNote)
  .add(subTrigger)
  .to(readNode)
  .to(existNode)
  .to(collectNode)
  .to(headerGate
    .onTrue(recNode.to(applyNode).to(retNode))
    .onFalse(errPrepNode.to(errDraftNode).to(retErrNode))
  );
